'use client';
import Link from 'next/link';
import { useMemo, useState } from 'react';
import { ApiError, api } from '@/lib/api';
import { ErrorBox, Loading, useApp, useAsync } from '@/components/app/AppShell';
import { useI18n, confirmDialog } from '@/components/Providers';

interface Rec { id: string; code: string | null; data: Record<string, any> }
interface Line { kind: string; desc: string; unit?: string; qty: number; unitCost: number }

/** Build: estimates (BOQ) with material / labour / other cost, markup and selling price; finalising creates the quotation. Plus printable progress claims. */
export default function Estimates() {
  const app = useApp(); const { locale } = useI18n(); const t = (ar: string, en: string) => (locale === 'ar' ? ar : en);
  const est = useAsync(() => api<Rec[]>('/tenant/p/boqEstimate?pageSize=100&sort=createdAt&dir=desc').then((r) => r.data), []); const clients = useAsync(() => api<Rec[]>('/tenant/p/client?pageSize=100').then((r) => r.data).catch(() => [] as Rec[]), []);
  const claims = useAsync(() => api<Rec[]>('/tenant/p/progressClaim?pageSize=100&sort=createdAt&dir=desc').then((r) => r.data).catch(() => [] as Rec[]), []); const projects = useAsync(() => api<Rec[]>('/tenant/p/project?pageSize=100').then((r) => r.data).catch(() => [] as Rec[]), []);
  const [tab, setTab] = useState<'estimates' | 'claims'>('estimates'); const [sel, setSel] = useState<{ type: 'est' | 'claim'; id: string } | null>(null); const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null); const [busy, setBusy] = useState('');
  const client = useMemo(() => new Map((clients.data ?? []).map((c) => [c.id, String(c.data.name)])), [clients.data]); const project = useMemo(() => new Map((projects.data ?? []).map((c) => [c.id, String(c.data.name ?? c.data.title ?? c.code)])), [projects.data]);
  if (!app.can('estimates.read')) return <div className="alert warn" role="alert">{t('لا تملك صلاحية عرض المقايسات.', 'You cannot view estimates.')}</div>;
  if (est.error) return <ErrorBox error={est.error} retry={est.reload} />; if (!est.data) return <Loading />;
  const m = app.money; const chosen = sel?.type === 'est' ? est.data.find((x) => x.id === sel.id) : undefined; const chosenClaim = sel?.type === 'claim' ? (claims.data ?? []).find((x) => x.id === sel.id) : undefined;
  async function finalise(e: Rec) {
    if (!(await confirmDialog(t('اعتماد المقايسة نهائيًا وإنشاء عرض السعر؟ لا يمكن تعديلها بعد ذلك.', 'Finalise this estimate and create the quotation? It cannot be edited afterwards.')))) return; setBusy(e.id); setMsg(null);
    try { await api(`/tenant/p/boqEstimate/${e.id}`, { method: 'PATCH', body: { status: 'final' } }); setMsg({ ok: true, text: t('تم الاعتماد وإنشاء عرض السعر.', 'Finalised; the quotation was created.') }); est.reload(); } catch (x) { setMsg({ ok: false, text: (x as ApiError).message }); } finally { setBusy(''); }
  }
  return (
    <>
      <div className="row between no-print"><h1 style={{ fontSize: '1.6rem', margin: 0 }}>{t('المقايسات والمستخلصات', 'Estimates & progress claims')}</h1>
        <div className="row"><div role="tablist" className="row" aria-label={t('القسم', 'Section')}>{(['estimates', 'claims'] as const).map((s) => <button key={s} role="tab" aria-selected={tab === s} className={`btn sm ${tab === s ? 'primary' : ''}`} onClick={() => { setTab(s); setSel(null); }}>{s === 'estimates' ? t('المقايسات', 'Estimates') : t('المستخلصات', 'Progress claims')}</button>)}</div>{tab === 'estimates' && app.can('estimates.create') && <Link className="btn primary" href="/app/e/boqEstimate/new">{t('مقايسة جديدة', 'New estimate')}</Link>}</div></div>
      {msg && <div className={`alert no-print ${msg.ok ? 'ok' : 'error'}`} role="alert">{msg.text}</div>}
      {tab === 'estimates' && (!est.data.length ? <div className="card no-print" style={{ textAlign: 'center' }}><p className="muted">{t('لا توجد مقايسات بعد.', 'No estimates yet.')}</p></div> :
        <div className="table-wrap no-print"><table><thead><tr><th scope="col">{t('الكود', 'Code')}</th><th scope="col">{t('المقايسة', 'Title')}</th><th scope="col">{t('العميل', 'Client')}</th><th scope="col">{t('مواد', 'Materials')}</th><th scope="col">{t('عمالة', 'Labour')}</th><th scope="col">{t('التكلفة', 'Cost')}</th><th scope="col">{t('سعر البيع', 'Selling')}</th><th scope="col">{t('الحالة', 'Status')}</th><th /></tr></thead>
          <tbody>{est.data.map((e) => <tr key={e.id}><td className="mono">{e.code}</td><td><b>{e.data.title}</b></td><td>{client.get(String(e.data.clientId)) ?? '—'}</td><td className="mono">{m(Number(e.data.materialCost ?? 0))}</td><td className="mono">{m(Number(e.data.labourCost ?? 0))}</td><td className="mono">{m(Number(e.data.totalCost ?? 0))}</td><td className="mono"><b>{m(Number(e.data.sellingPrice ?? 0))}</b></td><td><span className={`badge ${e.data.status === 'final' ? 'ok' : 'warn'}`}>{e.data.status === 'final' ? t('نهائية', 'Final') : t('مسودة', 'Draft')}</span>{e.data.quotationId && <div className="small muted">{t('تم إنشاء عرض سعر', 'Quotation created')}</div>}</td>
            <td className="row"><button className="btn sm" onClick={() => setSel({ type: 'est', id: e.id })}>{t('عرض / طباعة', 'View / print')}</button>{e.data.status === 'draft' && <Link className="btn sm" href={`/app/e/boqEstimate/${e.id}`}>{t('تعديل', 'Edit')}</Link>}{e.data.status === 'draft' && app.can('estimates.update') && <button className="btn sm primary" disabled={busy === e.id} onClick={() => finalise(e)}>{t('اعتماد وإنشاء عرض سعر', 'Finalise → quotation')}</button>}</td></tr>)}</tbody></table></div>)}
      {tab === 'claims' && ((claims.data ?? []).length ? <div className="table-wrap no-print"><table><thead><tr><th scope="col">{t('الكود', 'Code')}</th><th scope="col">{t('المشروع', 'Project')}</th><th scope="col">{t('رقم', 'No.')}</th><th scope="col">{t('حتى تاريخ', 'Up to')}</th><th scope="col">{t('الصافي', 'Net')}</th><th scope="col">{t('الحالة', 'Status')}</th><th /></tr></thead>
        <tbody>{(claims.data ?? []).map((c) => <tr key={c.id}><td className="mono">{c.code}</td><td>{project.get(String(c.data.projectId)) ?? '—'}</td><td>{c.data.no}</td><td className="mono">{c.data.periodTo}</td><td className="mono"><b>{m(Number(c.data.netAmount ?? 0))}</b></td><td><span className="badge">{String(c.data.status)}</span></td><td><button className="btn sm" onClick={() => setSel({ type: 'claim', id: c.id })}>{t('عرض / طباعة', 'View / print')}</button></td></tr>)}</tbody></table></div> : <div className="card no-print" style={{ textAlign: 'center' }}><p className="muted">{t('لا توجد مستخلصات.', 'No progress claims.')}</p></div>)}
      {chosen && <article className="card stack print-area" aria-label={t('مقايسة للطباعة', 'Printable estimate')}>
        <div className="row between"><div><h2 style={{ margin: 0 }}>{app.me.tenant.name}</h2><span className="muted small">{t('مقايسة', 'Estimate')} {chosen.code}</span></div><button className="btn no-print" onClick={() => window.print()}>{t('طباعة', 'Print')}</button></div>
        <p style={{ margin: 0 }}><b>{chosen.data.title}</b> — {client.get(String(chosen.data.clientId)) ?? ''}</p>
        <div className="table-wrap"><table><thead><tr><th scope="col">#</th><th scope="col">{t('البند', 'Item')}</th><th scope="col">{t('النوع', 'Type')}</th><th scope="col">{t('الوحدة', 'Unit')}</th><th scope="col">{t('الكمية', 'Qty')}</th><th scope="col">{t('سعر الوحدة', 'Unit cost')}</th><th scope="col">{t('الإجمالي', 'Total')}</th></tr></thead>
          <tbody>{((chosen.data.lines as Line[]) ?? []).map((l, i) => <tr key={i}><td>{i + 1}</td><td>{l.desc}</td><td>{l.kind}</td><td>{l.unit ?? ''}</td><td className="mono">{l.qty}</td><td className="mono">{m(l.unitCost)}</td><td className="mono">{m(l.qty * l.unitCost)}</td></tr>)}</tbody></table></div>
        <dl className="grid g4" style={{ margin: 0 }}><div><dt className="small muted">{t('مواد', 'Materials')}</dt><dd className="mono">{m(Number(chosen.data.materialCost ?? 0))}</dd></div><div><dt className="small muted">{t('عمالة', 'Labour')}</dt><dd className="mono">{m(Number(chosen.data.labourCost ?? 0))}</dd></div><div><dt className="small muted">{t('إجمالي التكلفة', 'Total cost')}</dt><dd className="mono">{m(Number(chosen.data.totalCost ?? 0))}</dd></div><div><dt className="small muted">{t('سعر البيع', 'Selling price')}</dt><dd className="mono"><b>{m(Number(chosen.data.sellingPrice ?? 0))}</b></dd></div></dl></article>}
      {chosenClaim && <article className="card stack print-area" aria-label={t('مستخلص للطباعة', 'Printable progress claim')}>
        <div className="row between"><div><h2 style={{ margin: 0 }}>{app.me.tenant.name}</h2><span className="muted small">{t('مستخلص رقم', 'Progress claim no.')} {chosenClaim.data.no} — {chosenClaim.code}</span></div><button className="btn no-print" onClick={() => window.print()}>{t('طباعة', 'Print')}</button></div>
        <p style={{ margin: 0 }}>{t('المشروع: ', 'Project: ')}<b>{project.get(String(chosenClaim.data.projectId)) ?? ''}</b> · {t('حتى تاريخ ', 'up to ')}<span className="mono">{chosenClaim.data.periodTo}</span></p>
        <div className="table-wrap"><table><tbody>{([[t('إجمالي الأعمال التراكمي', 'Cumulative value'), chosenClaim.data.cumulativeValue], [t('الأعمال السابقة', 'Previously claimed'), chosenClaim.data.previousCumulative], [t('قيمة هذا المستخلص', 'This claim (gross)'), chosenClaim.data.grossAmount], [t('الاحتجاز', 'Retention'), chosenClaim.data.retentionAmount], [t('الخصومات', 'Deductions'), chosenClaim.data.deductions]] as [string, unknown][]).map(([k, v]) => <tr key={k}><th scope="row">{k}</th><td className="mono">{m(Number(v ?? 0))}</td></tr>)}<tr><th scope="row">{t('الصافي المستحق', 'Net due')}</th><td className="mono"><b>{m(Number(chosenClaim.data.netAmount ?? 0))}</b></td></tr></tbody></table></div>
        {chosenClaim.data.notes && <p style={{ whiteSpace: 'pre-wrap' }}>{String(chosenClaim.data.notes)}</p>}
        <div className="grid g2" style={{ marginTop: 32 }}><div style={{ borderTop: '1px solid currentColor', paddingTop: 6 }}>{t('توقيع المقاول', 'Contractor signature')}</div><div style={{ borderTop: '1px solid currentColor', paddingTop: 6 }}>{t('توقيع العميل', 'Client signature')}</div></div></article>}
    </>
  );
}
